# Shared helpers for the Java audit fact sheets: comment/string stripping and brace matching.
# Regex-based on purpose (no parser dependency); every heuristic yields candidates, never verdicts.
import os
import re


def strip_java(src):
    """Blank out comments, string/char literals and text blocks, keeping offsets and newlines."""
    out = list(src)
    i, n = 0, len(src)

    def blank(a, b):
        for k in range(a, b):
            if out[k] != '\n':
                out[k] = ' '

    while i < n:
        c = src[i]
        if src.startswith('//', i):
            j = src.find('\n', i)
            j = n if j < 0 else j
            blank(i, j)
            i = j
        elif src.startswith('/*', i):
            j = src.find('*/', i + 2)
            j = n if j < 0 else j + 2
            blank(i, j)
            i = j
        elif src.startswith('"""', i):
            j = src.find('"""', i + 3)
            j = n if j < 0 else j + 3
            blank(i + 1, j - 1)
            i = j
        elif c == '"' or c == "'":
            j = i + 1
            while j < n and src[j] != c and src[j] != '\n':
                j += 2 if src[j] == '\\' else 1
            j = min(j + 1, n)
            blank(i + 1, j - 1)
            i = j
        else:
            i += 1
    return ''.join(out)


def match_brace(s, open_idx):
    """Index of the brace closing the one at open_idx, or len(s)."""
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def match_paren(s, open_idx):
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def line_of(s, idx):
    return s.count('\n', 0, idx) + 1


MODIFIERS = r'(?:(?:public|protected|private|static|final|synchronized|abstract|native|default|strictfp)\s+)*'
METHOD_RE = re.compile(
    r'(?P<annos>(?:@\w+(?:\.\w+)*(?:\([^()]*(?:\([^()]*\)[^()]*)*\))?\s+)*)'
    r'(?P<mods>' + MODIFIERS + r')'
    r'(?:<[^<>]*(?:<[^<>]*>[^<>]*)*>\s+)?'
    r'(?P<ret>[\w.$]+(?:<[^;{}()]*?>)?(?:\[\])*)\s+'
    r'(?P<name>[a-zA-Z_$][\w$]*)\s*\((?P<params>[^;{}()]*(?:\([^()]*\)[^;{}()]*)*)\)\s*'
    r'(?:throws\s+[\w.$,\s]+)?\{')
CTOR_KEYWORDS = {'if', 'for', 'while', 'switch', 'catch', 'synchronized', 'return', 'new', 'else', 'try', 'do'}


def methods(stripped):
    """Method declarations with body span: dicts name/mods/annos/params/start/end/line."""
    found = []
    for m in METHOD_RE.finditer(stripped):
        name = m.group('name')
        if name in CTOR_KEYWORDS or m.group('ret') in CTOR_KEYWORDS:
            continue
        body_open = m.end() - 1
        found.append({
            'name': name,
            'mods': m.group('mods').split(),
            'annos': m.group('annos'),
            'params': m.group('params').strip(),
            'ret': m.group('ret'),
            'start': body_open,
            'end': match_brace(stripped, body_open),
            'line': line_of(stripped, m.start('name')),
        })
    return found


def java_files(root):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target')))
        for f in sorted(filenames):
            if f.endswith('.java'):
                yield os.path.join(dirpath, f)


def java_version(base):
    """(version, source) from Maven or Gradle build files, or (None, reason)."""
    pats = [
        (r'<maven\.compiler\.release>\s*(\d+)', 'maven.compiler.release'),
        (r'<java\.version>\s*(\d+)', 'java.version'),
        (r'<release>\s*(\d+)\s*</release>', 'compiler release'),
        (r'<maven\.compiler\.source>\s*(?:1\.)?(\d+)', 'maven.compiler.source'),
        (r'JavaLanguageVersion\.of\(\s*(\d+)', 'gradle toolchain'),
        (r'sourceCompatibility\s*=\s*[\'"]?(?:JavaVersion\.VERSION_)?(?:1[._])?(\d+)', 'gradle sourceCompatibility'),
    ]
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target'))]
        if dirpath.count(os.sep) - base.count(os.sep) > 2:
            dirnames[:] = []
        for f in ('pom.xml', 'build.gradle', 'build.gradle.kts'):
            if f in filenames:
                try:
                    text = open(os.path.join(dirpath, f), encoding='utf-8', errors='replace').read()
                except OSError:
                    continue
                for pat, label in pats:
                    m = re.search(pat, text)
                    if m:
                        return int(m.group(1)), os.path.relpath(os.path.join(dirpath, f), base) + ' ' + label
    return None, 'no pom.xml/build.gradle with a Java version found'


class Sheet:
    """Collects TREFFER lines per kind with a cap, then prints FAKT counts and the hits."""

    def __init__(self, cap):
        self.cap = cap
        self.hits = {}

    def hit(self, kind, text):
        self.hits.setdefault(kind, []).append(text)

    def count(self, kind):
        return len(self.hits.get(kind, []))

    def emit(self, kinds):
        for kind in kinds:
            rows = self.hits.get(kind, [])
            print('FAKT %s_count: %d' % (kind, len(rows)))
        print('')
        for kind in kinds:
            rows = self.hits.get(kind, [])
            for r in rows[:self.cap]:
                print('TREFFER %s: %s' % (kind, r))
            if len(rows) > self.cap:
                print('# %d more %s hits not listed' % (len(rows) - self.cap, kind))


# Fact sheet for the Java concurrency audit. Usage: concurrency_facts.py <repo-root> <source-dir>
import os
import re
import sys


BLOCKING = [
    ('sleep', r'\bThread\.sleep\s*\('),
    ('wait/join', r'(?<!String)\.(?:wait|join|await|waitFor)\s*\('),
    ('future.get', r'\b\w*[Ff]uture\w*\.get\s*\('),
    ('process', r'\bProcessBuilder\b|\bRuntime\.getRuntime\(\)\.exec\s*\('),
    ('docker', r'\b\w+Cmd\s*\(|\bDockerClient\b|\bdocker\w*\.\w+\s*\('),
    ('http', r'\bHttpClient\b|\.send(?:Async)?\s*\(|\bRestTemplate\b|\bRestClient\b|\bWebClient\b|\.block\s*\(\s*\)|\bopenConnection\s*\('),
    ('database', r'\b\w*[Rr]epository\.\w+\s*\(|\b[jJ]dbcTemplate\b|\.execute(?:Query|Update)\s*\(|\bentityManager\.\w+\s*\(|\b\w*[tT]ransactionTemplate\.\w+\s*\(|\.getConnection\s*\('),
    ('file-io', r'\bFiles\.\w+\s*\(|\bnew\s+File(?:Input|Output)Stream\b|\bnew\s+(?:FileReader|FileWriter|RandomAccessFile)\b'),
    ('stream-io', r'\.(?:readLine|readAllBytes|transferTo)\s*\(|\bnew\s+Socket\b'),
    ('cli', r'\b\w*(?:[Ee]xecutor[Ss]ervice|[Cc]ommand[Ss]ervice|[Ss]hell\w*)\.(?:execute|run)\w*\s*\('),
]
BLOCKING_RE = [(label, re.compile(p)) for label, p in BLOCKING]
CALL_RE = re.compile(r'(?<![\w.$])(?:this\.)?([a-z_$][\w$]*)\s*\(')


def blocking_in(text):
    for label, rx in BLOCKING_RE:
        m = rx.search(text)
        if m:
            return label, m.start()
    return None


def expand(s, by_name, body, own_pos, depth, chain=()):
    """Follow calls to methods of the same file (up to depth hops) and return the first blocking call."""
    for c in CALL_RE.finditer(body):
        for target in by_name.get(c.group(1), []):
            if target['start'] <= own_pos <= target['end'] or target['name'] in chain:
                continue
            tbody = s[target['start']:target['end']]
            inner = blocking_in(tbody)
            path = chain + (target['name'],)
            if inner:
                via = ' via ' + ' -> '.join('%s()' % n for n in path) + ' from line %d' % target['line']
                return (inner[0], target['start'] + inner[1]), via
            if depth > 1:
                hop = expand(s, by_name, tbody, target['start'], depth - 1, path)
                if hop:
                    return hop
    return None


def main():
    base = os.path.abspath(sys.argv[1])
    src_root = os.path.join(base, sys.argv[2])
    sheet = Sheet(cap=40)
    files = 0
    sync_sites = 0
    vthread_sites = []

    print('## FAKTENBLATT')
    print('# Measured deterministically (regex over the source, comments and strings removed).')
    print('# TREFFER lines are candidates with a location, not proof; check each one in the source.')
    print('')

    version, vsrc = java_version(base)
    if version is None:
        print('NICHT GEMESSEN: java_version (%s)' % vsrc)
    else:
        print('FAKT java_version: %d (%s)' % (version, vsrc))

    if not os.path.isdir(src_root):
        print('NICHT GEMESSEN: java_files_scanned (source directory %s missing)' % sys.argv[2])
        return

    for cfg_dir, _, cfg_files in os.walk(base):
        rel_dir = os.path.relpath(cfg_dir, base)
        if any(part.startswith('.') and part != '.' or part.startswith('target') or part in ('build', 'node_modules', 'test')
               for part in rel_dir.split(os.sep)):
            continue
        for f in cfg_files:
            if re.match(r'application.*\.(ya?ml|properties)$', f):
                p = os.path.join(cfg_dir, f)
                try:
                    text = open(p, encoding='utf-8', errors='replace').read()
                except OSError:
                    continue
                if re.search(r'virtual\s*:\s*\n\s*enabled\s*:\s*true|threads\.virtual\.enabled\s*[=:]\s*true', text):
                    vthread_sites.append('%s spring.threads.virtual.enabled=true' % os.path.relpath(p, base))

    for path in java_files(src_root):
        rel = os.path.relpath(path, base)
        try:
            raw = open(path, encoding='utf-8', errors='replace').read()
        except OSError:
            continue
        files += 1
        s = strip_java(raw)
        meths = methods(s)
        by_name = {}
        for m in meths:
            by_name.setdefault(m['name'], []).append(m)

        for m in re.finditer(r'\bnewVirtualThreadPerTaskExecutor\s*\(|\bThread\.ofVirtual\s*\(|\bThread\.startVirtualThread\s*\(', s):
            vthread_sites.append('%s:%d %s' % (rel, line_of(s, m.start()), m.group(0).rstrip('( ')))

        # synchronized blocks and synchronized methods, with one level of same-file call expansion
        regions = []
        for m in re.finditer(r'\bsynchronized\s*\(', s):
            p_close = match_paren(s, m.end() - 1)
            lock = re.sub(r'\s+', ' ', s[m.end():p_close]).strip()
            b_open = s.find('{', p_close)
            if b_open < 0:
                continue
            regions.append((m.start(), b_open, match_brace(s, b_open), 'synchronized(%s)' % lock[:80]))
        for m in meths:
            if 'synchronized' in m['mods']:
                regions.append((m['start'], m['start'], m['end'], 'synchronized method %s()' % m['name']))
        for start, b_open, b_end, what in regions:
            sync_sites += 1
            body = s[b_open:b_end]
            found = blocking_in(body)
            via = ''
            if not found:
                hop = expand(s, by_name, body, b_open, depth=2)
                if hop:
                    found, via = hop
            else:
                found = (found[0], b_open + found[1])
            if found:
                sheet.hit('blocking_in_synchronized', '%s:%d %s -> %s in line %d%s' % (
                    rel, line_of(s, start), what, found[0], line_of(s, found[1]), via))

        # ThreadLocal declarations
        for m in re.finditer(r'\bThreadLocal\s*<[^;=]*>\s+(\w+)\s*=', s):
            has_remove = re.search(r'\b%s\.remove\s*\(' % re.escape(m.group(1)), s) is not None
            sheet.hit('threadlocal', '%s:%d %s (remove in the same file: %s)' % (
                rel, line_of(s, m.start()), m.group(1), 'yes' if has_remove else 'no'))

        # @Async: non-public methods and calls from the same class (proxy bypass)
        for m in meths:
            if re.search(r'@Async\b', m['annos']):
                if 'public' not in m['mods']:
                    sheet.hit('async_non_public', '%s:%d %s()' % (rel, m['line'], m['name']))
                for c in re.finditer(r'(?<![\w.$])(?:this\.)?%s\s*\(' % re.escape(m['name']), s):
                    if m['start'] <= c.start() <= m['end'] or abs(line_of(s, c.start()) - m['line']) == 0:
                        continue
                    sheet.hit('async_self_call', '%s:%d %s() is called in the same class (declared at line %d)' % (
                        rel, line_of(s, c.start()), m['name'], m['line']))

        # CompletableFuture started without error handling, timeout or explicit executor
        for m in re.finditer(r'\bCompletableFuture\s*\.\s*(supplyAsync|runAsync)\s*\(', s):
            p_close = match_paren(s, m.end() - 1)
            args = s[m.end():p_close]
            depth, top_commas = 0, 0
            for ch in args:
                depth += ch in '([{'
                depth -= ch in ')]}'
                top_commas += ch == ',' and depth == 0
            stmt_end = s.find(';', p_close)
            chain = s[p_close:stmt_end if stmt_end > 0 else len(s)]
            ln = line_of(s, m.start())
            if top_commas == 0:
                sheet.hit('future_common_pool', '%s:%d %s without executor (ForkJoinPool.commonPool)' % (rel, ln, m.group(1)))
            if not re.search(r'\.(exceptionally|handle|whenComplete|orTimeout|completeOnTimeout|join|get)\w*\s*\(', chain):
                sheet.hit('future_unhandled', '%s:%d %s without exceptionally/handle/whenComplete/timeout in the same statement' % (rel, ln, m.group(1)))

        # executors created outside try-with-resources and never shut down in the file
        closes = re.search(r'\.(shutdown|shutdownNow|close)\s*\(|@PreDestroy|DisposableBean|\bdestroy\s*\(', s)
        for m in re.finditer(r'\bExecutors\.new\w+\s*\(|\bnew\s+(?:Scheduled)?ThreadPoolExecutor\s*\(', s):
            head = s[max(0, s.rfind('\n', 0, m.start()) - 200):m.start()]
            if re.search(r'\btry\s*\([^)]*$', head):
                continue
            enclosing = [mm for mm in meths if mm['start'] <= m.start() <= mm['end']]
            if enclosing and re.search(r'@Bean\b', enclosing[-1]['annos']):
                continue
            if not closes:
                sheet.hit('executor_not_closed', '%s:%d %s without shutdown/close/@PreDestroy in the file' % (
                    rel, line_of(s, m.start()), m.group(0).rstrip('( ')))

        # static mutable collections shared across threads
        for m in re.finditer(r'\bstatic\s+(?:final\s+)?[\w.<>,?\s\[\]]+?\s+(\w+)\s*=\s*new\s+(HashMap|ArrayList|HashSet|LinkedList|TreeMap|LinkedHashMap|LinkedHashSet|ArrayDeque)\b', s):
            sheet.hit('static_mutable_collection', '%s:%d %s = new %s' % (rel, line_of(s, m.start()), m.group(1), m.group(2)))

        # check-then-act on a map field
        for m in re.finditer(r'\bif\s*\(\s*!?\s*(\w+)\.containsKey\s*\(', s):
            b_open = s.find('{', m.end())
            window = s[m.end():match_brace(s, b_open) if b_open > 0 else m.end() + 300]
            if re.search(r'\b%s\.put\s*\(' % re.escape(m.group(1)), window):
                sheet.hit('check_then_act', '%s:%d %s.containsKey + put' % (rel, line_of(s, m.start()), m.group(1)))

        # lock maps that only grow
        for m in re.finditer(r'(\w+)\.computeIfAbsent\s*\([^;]*?->\s*new\s+(Object|ReentrantLock|ReentrantReadWriteLock|Semaphore)\s*\(', s):
            if not re.search(r'\b%s\.(remove|clear)\s*\(' % re.escape(m.group(1)), s):
                sheet.hit('lock_map_unbounded', '%s:%d %s grows per key, never removed' % (rel, line_of(s, m.start()), m.group(1)))

    print('FAKT java_files_scanned: %d' % files)
    print('FAKT synchronized_sites: %d' % sync_sites)
    print('FAKT virtual_thread_sites: %d' % len(vthread_sites))
    if version is not None:
        pinning = version < 24 and bool(vthread_sites)
        print('FAKT carrier_pinning_relevant: %s (Java %d %s 24, virtual threads %s)' % (
            'yes' if pinning else 'no', version, '<' if version < 24 else '>=', 'used' if vthread_sites else 'not found'))
    else:
        print('NICHT GEMESSEN: carrier_pinning_relevant (Java version unknown)')
    kinds = ['blocking_in_synchronized', 'threadlocal', 'async_non_public', 'async_self_call',
             'future_common_pool', 'future_unhandled', 'executor_not_closed',
             'static_mutable_collection', 'check_then_act', 'lock_map_unbounded']
    sheet.emit(kinds)
    for v in vthread_sites[:15]:
        print('TREFFER virtual_thread_site: %s' % v)
    if len(vthread_sites) > 15:
        print('# %d more virtual_thread_site hits not listed' % (len(vthread_sites) - 15))
    print('')
    print('## PFLICHTFELDER')
    print('PFLICHT-FAKTEN: java_files_scanned synchronized_sites blocking_in_synchronized_count pmd_threads_findings')


if __name__ == '__main__':
    main()
PYEOF
